package com.dentalclinic.patientcare.entity;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.time.*;
@Entity @Table(name="patient_submissions") public class PatientSubmission { public enum Type{INQUIRY,FEEDBACK} public enum Status{SUBMITTED,IN_REVIEW,RESOLVED}
@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotNull private Long patientId; @Enumerated(EnumType.STRING) @NotNull private Type type; @NotBlank @Size(max=120) private String subject; @NotBlank @Size(max=1500) private String message; @Min(1) @Max(5) private Integer rating; @Enumerated(EnumType.STRING) private Status status=Status.SUBMITTED; private LocalDateTime submittedAt;
@PrePersist void pre(){submittedAt=LocalDateTime.now();if(status==null)status=Status.SUBMITTED;}
public Long getId(){return id;}public void setId(Long v){id=v;}public Long getPatientId(){return patientId;}public void setPatientId(Long v){patientId=v;}public Type getType(){return type;}public void setType(Type v){type=v;}public String getSubject(){return subject;}public void setSubject(String v){subject=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public Integer getRating(){return rating;}public void setRating(Integer v){rating=v;}public Status getStatus(){return status;}public void setStatus(Status v){status=v;}public LocalDateTime getSubmittedAt(){return submittedAt;}}
// LEADER MERGE: US08 owns patient submission. Reports/Inquiry/Feedback module can manage status/response using this shared table/API rather than creating a second submission table.
